mapper.sql:
		WHERE od.ENT_CODE = #{srchEntCode}



			AND ISNULL(CLEARANCE_VIOLATION_REASON, '') != ''


			AND CLEARANCE_STATUS = #{clearanceStatus}




			AND od.CD_TYPE = #{cdType}


			AND DROP_YN = #{dropYN}


			AND INSPECTION_YN =  #{inspectionYN}


			AND SE_INSPECTION_YN = #{seInspectionYN}


			AND XRAY_YN = #{xray}


			AND INSPECTION_TYPE = #{inspectionType}


			AND CLEARANCE_NOTICE_YN = #{clearanceNoticeYN}


		AND od.SOLUTION = #{srchSolution}


		AND od.BL_TYPE_MH = #{srchBlTypeMh}




			AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
			AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))


			AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
			AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})




			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'


			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'









		AND od.BOUND_TYPE = #{srchBoundType2}


		AND od.CONSOL_YN = #{srchConsolYn}


		AND ad.CLEARANCE_STATUS = (#{srchClearanceStatus})


		AND od.CD_TYPE = #{srchCdType}



		AND ad.CLEARANCE_STATUS IN (#{item} ) 


		AND (1 = 0



			OR od.CD_TYPE = #{item}


			OR od.CD_TYPE IN ('N', 'B') OR ad.DROP_YN = 'Y'



		)




			AND od.CD_TYPE IN (#{item})


			AND (od.CD_TYPE IN ('N', 'B') OR ad.DROP_YN = 'Y')



			AND od.MULTI_YN = 'Y'


			AND ISNULL(od.MULTI_YN, 'N') = 'N'
-- 				AND od.PIECES > 1



		AND od.FINISH_YN = #{srchFinishYn}


		AND ad.CUSTOMS_ID_VERIFY = #{srchCustomsIdVerify}


		AND ad.CUSTOMS_ID_VERIFY IN (#{item})


		AND ad.SMS_INFORM_YN = 'Y' AND (ad.SMS_INFORM_RES_YN IS NULL OR ad.SMS_INFORM_RES_YN = 'N')


		AND (ad.SMS_INFORM_YN IS NULL OR ad.SMS_INFORM_YN = '' OR ad.SMS_INFORM_YN = 'N')


		AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'Y')


		AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'N')


		AND od.CLEARANCE_NOTICE_YN = #{srchClearanceNoticeYn}


		AND ad.CLEARANCE_YN = #{srchClearanceYn}


		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0


		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') = 0




		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO) > 0


		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_CODE = #{srchHoldCode}) > 0




		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN IN ('Y','N')) > 0


		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'Y') > 0


		AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0


		AND (od.CLEARANCE_VIOLATION_CODE IS NOT NULL AND od.CLEARANCE_VIOLATION_CODE != '')


		AND (od.CLEARANCE_VIOLATION_CODE IS NULL OR od.CLEARANCE_VIOLATION_CODE = '')


		AND ad.CARRYIN_DATE IS NOT NULL


		AND ad.CARRYIN_DATE IS NULL


		AND ad.CARRYOUT_DATE IS NOT NULL


		AND ad.CARRYOUT_DATE IS NULL


		AND ad.MF_DATE IS NOT NULL


		AND ad.MF_DATE IS NULL


		AND (od.DELIVERY_NAME_CHANGED IS NOT NULL OR od.DELIVERY_NAME_CHANGED != '')


		AND (od.DELIVERY_NAME_CHANGED IS NULL OR od.DELIVERY_NAME_CHANGED = '')


		AND (od.DELIVERY_ADDRESS_CHANGED IS NOT NULL OR od.DELIVERY_NAME_CHANGED != '')


		AND (od.DELIVERY_ADDRESS_CHANGED IS NULL OR od.DELIVERY_NAME_CHANGED = '')


		AND od.SHIPPER_NAME = #{srchShipperName}


		AND (od.CONSIGNEE_NAME = #{srchConsigneeName} OR od.CONSIGNEE_NAME_LOC = #{srchConsigneeName})



		AND ( 		(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') IS NOT NUll
				AND (SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') != 0 )



 		AND ( 		(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') IS NUll
  				OR  (SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') = 0 )


		AND od.BL_TYPE_IERT = #{srchBlTypeIert}







				AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) LIKE CONCAT(#{srchNo},'%')




						AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) IN (#{item})


						AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) = #{srchNo}








					AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')




							AND ${srchNoType} IN (#{item})


							AND ${srchNoType} = #{srchNo}










			AND (SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = ${srchCusType}) LIKE CONCAT('%',#{srchCus},'%')


			AND ${srchCusType} = #{srchCus}




		AND od.OD_JOB_NO IN (#{item})


		AND ad.LAST_POD_STATUS >= #{srchLastPodStatusMin}


		AND ad.LAST_POD_STATUS = #{srchLastPodStatus}


		AND ad.LAST_POD_STATUS IN (#{item})








		AND od.VESSEL_FLIGHT = #{srchVesselFlight}


		AND od.ORIG_CODE = #{srchOrigCode}


		AND od.DEST_CODE = #{srchDestCode}


		AND od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}





			AND (


					(od.MASTER_OD_JOB_NO IN ${srchMasterOdJobNoListStr} AND ad.SIMPLE_DOC_NO IS NULL)


					OR ad.SIMPLE_DOC_NO IN(#{item}) 


			)




			AND od.MASTER_OD_JOB_NO IN ${srchMasterOdJobNoListStr}


			AND ad.SIMPLE_DOC_NO IN(#{item}) 





		AND od.OD_JOB_NO = #{srchHouseOdJobNo}


		AND od.MBL_NO = #{srchMblNo}


		AND od.HBL_NO = #{srchHblNo}


		AND od.PO_NO = #{srchPoNo}


		AND ad.WH_LOCATION = #{srchWhLocation}




			AND ISNULL(ad.PRINT_YN, 'N') = 'N'


			AND ad.PRINT_YN = #{printYn}




		AND od.CB_CODE = #{srchCbCode}


		AND od.OD_JOB_NO = #{srchOdJobNo}


		AND ISNULL(od.DELIVERY_ADDRESS_CHANGED,'') <> ''


		AND cs.CS_TYPE = #{srchCsType}


		AND cs.CS_TYPE IN (#{item})


		AND od.DELIVERY_CODE = #{srchDeliveryCode}


		AND od.ECM_TYPE = #{srchEcmType}


		AND od.ECM_BUY_TYPE = #{srchEcmBuyType}


		AND od.DELIVERY_CODE IN (#{item})


		AND(


				ad.CARRYIN_DATE IS NOT NULL
				ad.CARRYIN_DATE IS NULL
				ad.CARRYOUT_DATE IS NOT NULL
				ad.CARRYOUT_DATE IS NULL
				(ad.CARRYIN_DATE IS NOT NULL AND ad.CARRYOUT_DATE IS NULL)


		)


		AND od.DELIVERY_CODE IS NOT NULL
		AND od.DELIVERY_CODE != ''




			AND(1 = 0

			OR od.INSPECTION_YN = #{srchInspectionYn}


			OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


			OR ad.XRAY_YN = #{srchXrayYn}


			OR ad.DROP_YN = #{srchDropYn}


			OR ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}


			OR ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}


			AND ISNULL((SELECT TOP 1 ABNORMAL_CODE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO),'') != ''


	        OR (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0
			OR (ISNULL(CLEARANCE_VIOLATION_CODE, '') != '' OR ISNULL(CLEARANCE_VIOLATION_REASON, '') != '')


			OR ad.CRIME_SELECTION_YN = #{srchCriminalYn}

			)



			AND od.INSPECTION_YN = #{srchInspectionYn}


			AND ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


			AND ad.XRAY_YN = #{srchXrayYn}


			AND ad.DROP_YN = #{srchDropYn}


			AND ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}


			AND ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}




			AND ad.LAST_POD_STATUS != 'ECM040'


			AND od.CD_TYPE in ('Y','N')


			AND od.CD_TYPE = 'N'


			AND ad.EMS_YN = 'Y'




					AND od.RETURN_YN = 'Y'


					AND (ISNULL(od.RETURN_YN,'') = '' OR od.RETURN_YN = 'N')






					AND (od.RETURN_YN = 'Y' AND ISNULL(od.RETURN_DELIVERY_NO,'') != '')   


					AND (od.RETURN_YN = 'Y' AND ISNULL(od.RETURN_DELIVERY_NO,'') = '')   




			AND od.CUST_CODE_LV1 = #{srchEcmCustomerCode}


			AND od.ECM_YN = #{srchEcmYn}

mapper.select:
/* OrderMapper.selectOrderListDay : Order List(일일보고) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT B.* ,STUFF((SELECT ',' + CNTR_NO FROM TB_ECM_OD_CONTAINER AS t2 WHERE t2.OD_JOB_NO = B.OD_JOB_NO GROUP BY CNTR_NO FOR XML PATH('')), 1, 1, '') AS CNTR_NO ,STUFF((SELECT ',' + CNTR_CODE FROM TB_ECM_OD_CONTAINER AS t2 WHERE t2.OD_JOB_NO = B.OD_JOB_NO GROUP BY CNTR_CODE FOR XML PATH('')), 1, 1, '') AS CNTR_CODE FROM (SELECT A.* ,A.HBL_CNT - A.CARRYIN_CNT AS NO_CARRYIN_CNT ,A.CLEARANCE_CNT / A.HBL_CNT * 100 AS CLEARANCE_PERCENT ,A.DELIVERY_CNT / A.HBL_CNT * 100 AS DELIVERY_PERCENT ,A.CARRYIN_CNT - A.CARRYOUT_CNT AS STOCK
,COUNT(A.MASTER_OD_JOB_NO) OVER() AS TOTAL_CNT ,SUM(A.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT ,SUM(A.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT ,SUM(A.IMPLEMENTATION_CNT) OVER() AS TOTAL_IMPLEMENTATION_CNT ,SUM(A.EXCLUDE_CNT) OVER() AS TOTAL_EXCLUDE_CNT ,SUM(A.INSPECTION_CNT) OVER() AS TOTAL_INSPECTION_CNT ,SUM(A.SE_INSPECTION_CNT) OVER() AS TOTAL_SE_INSPECTION_CNT ,SUM(A.XRAY_CNT) OVER() AS TOTAL_XRAY_CNT ,SUM(A.DROP_CNT) OVER() AS TOTAL_DROP_CNT ,SUM(A.UNUSUAL_CNT) OVER() AS TOTAL_UNUSUAL_CNT ,SUM(A.CARRYIN_CNT) OVER() AS TOTAL_CARRYIN_CNT ,SUM(A.CARRYOUT_CNT) OVER() AS TOTAL_CARRYOUT_CNT ,SUM(A.CLEARANCE_CNT) OVER() AS TOTAL_CLEARANCE_CNT ,SUM(A.DELIVERY_RECV_CNT) OVER() AS TOTAL_DELIVERY_RECV_CNT ,SUM(A.CLEARANCE_VIOLATION_CNT) OVER() AS TOTAL_CLEARANCE_VIOLATION_CNT ,SUM(A.HBL_CNT) OVER() - SUM(A.CARRYIN_CNT) OVER() AS TOTAL_NO_CARRYIN_CNT FROM( SELECT od.MASTER_OD_JOB_NO ,od.CUST_CODE_LV2 ,MAX(od.OD_JOB_NO) AS OD_JOB_NO ,MAX(od.CUST_CODE_LV1) AS CUST_CODE_LV1 ,MAX(od.AR_DATE) AS AR_DATE ,MAX(od.MBL_NO) AS MBL_NO ,MAX(od.VESSEL_FLIGHT) AS VESSEL_FLIGHT ,MAX(od.ORIG_CODE) AS ORIG_CODE ,MAX(od.CB_NAME) AS CB_NAME ,MAX(od.ENT_CODE) AS ENT_CODE ,MAX(od.DEST_CODE) AS DEST_CODE ,MAX(od.OB_DATE) AS OB_DATE ,COUNT(od.OD_JOB_NO) AS HBL_CNT ,COUNT(CASE od.CD_TYPE WHEN 'Y' THEN 1 END) AS SIMPLE_CNT ,COUNT(CASE od.CD_TYPE WHEN 'N' THEN 1 END) AS GENERAL_CNT ,COUNT(CASE od.CD_TYPE WHEN 'E' THEN 1 END) AS IMPLEMENTATION_CNT ,COUNT(CASE od.CD_TYPE WHEN 'B' THEN 1 END) AS EXCLUDE_CNT ,COUNT(CASE od.INSPECTION_YN WHEN 'Y' THEN 1 END) AS INSPECTION_CNT ,COUNT(CASE ad.SE_INSPECTION_YN WHEN 'Y' THEN 1 END) AS SE_INSPECTION_CNT ,COUNT(CASE ad.XRAY_YN WHEN 'Y' THEN 1 END) AS XRAY_CNT ,COUNT(CASE ad.DROP_YN WHEN 'Y' THEN 1 END) AS DROP_CNT , COUNT(CASE WHEN ad.DROP_YN = 'Y' OR ad.ABNORMAL_DATE IS NOT NULL THEN 1 END) AS UNUSUAL_CNT ,COUNT(CASE WHEN ad.CARRYIN_DATE IS NOT NULL THEN 1 END) AS CARRYIN_CNT ,COUNT(CASE WHEN ad.CARRYOUT_DATE IS NOT NULL THEN 1 END) AS CARRYOUT_CNT ,COUNT(CASE ad.CLEARANCE_YN WHEN 'Y' THEN 1 END) AS CLEARANCE_CNT ,COUNT(CASE WHEN ad.DELIVERY_RECV_DATE IS NOT NULL THEN 1 END) AS DELIVERY_RECV_CNT ,COUNT(CASE WHEN ISNULL(od.CLEARANCE_VIOLATION_CODE, '') != '' THEN 1 END) AS CLEARANCE_VIOLATION_CNT ,COUNT(CASE ad.DELIVERY_YN WHEN 'Y' THEN 1 END) AS DELIVERY_CNT ,SUM(od.GWT) AS GWT ,SUM(od.CBM) AS CBM ,COUNT(CASE WHEN ISNULL(od.ECM_YN,'') = 'Y' THEN 1 END) AS ECM_Y_CNT ,COUNT(CASE WHEN ISNULL(od.ECM_YN,'') = '' OR od.ECM_YN = 'N' THEN 1 END) AS ECM_N_CNT FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO
AND od.MASTER_OD_JOB_NO IS NOT NULL GROUP BY od.MASTER_OD_JOB_NO, od.CUST_CODE_LV2 ) A ) B

/* OrderMapper.selectOrderListDayHouse : Order List(일일보고 하우스) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.MBL_NO ,od.HBL_NO ,od.OB_DATE ,od.AR_DATE ,od.PIECES ,od.GWT ,(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.CUSTOMS_ID_TYPE AND GROUP_CODE = 'CUSTOMS_ID_TYPE') AS CUSTOMS_ID_TYPE ,od.INSPECTION_YN ,ad.SE_INSPECTION_YN ,ad.DROP_YN ,CASE WHEN ad.LAST_POD_STATUS IN('ECM160', 'ECM220', 'ECM230', 'ECM300') THEN 'Y' ELSE 'N' END AS UNUSUAL_YN ,ad.XRAY_YN ,CASE WHEN ISNULL(ad.CARRYIN_DATE, '') = '' THEN 'N' ELSE 'Y' END AS CARRYIN_YN ,ad.CARRYIN_DATE ,CASE WHEN ISNULL(ad.CARRYOUT_DATE, '') = '' THEN 'N' ELSE 'Y' END AS CARRYOUT_YN ,ad.CARRYOUT_DATE ,ad.CLEARANCE_YN ,ad.CLEARANCE_DATE ,CASE WHEN ad.DELIVERY_RECV_DATE IS NOT NULL THEN 'Y' ELSE 'N' END AS DELIVERY_RECV_YN ,ad.DELIVERY_RECV_DATE ,CASE WHEN od.CLEARANCE_VIOLATION_CODE IS NOT NULL THEN 'Y' ELSE 'N' END AS CLEARANCE_VIOLATION_YN ,od.AMOUNT_CUR ,od.COMMODITY_ITEM ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME ,od.CONSIGNEE_NAME_LOC ,od.REMARKS
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND(
(
od.MASTER_OD_JOB_NO = #{item.srchMasterOdJobNo}
1 = 0
AND od.CUST_CODE_LV2 = #{item.srchCustCodeLv2}
AND od.CUST_CODE_LV2 IS NULL
)
)

/* OrderMapper.selectBatchTargetCountChk : 일괄변경대상건수조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SELECT COUNT(od.OD_JOB_NO) CNT FROM TB_ECM_OD od
INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE (
(od.MASTER_OD_JOB_NO = #{item.odJobNo} AND ISNULL(ad.SIMPLE_DOC_NO, '') = ISNULL(CAST(#{item.simpleDocNo} AS VARCHAR(20)), ''))
)
WHERE od.MASTER_OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H'

/* OrderMapper.selectOrderListSumHouse : Order List(Summary - House) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.MBL_NO ,od.HBL_NO ,od.OB_DATE ,od.AR_DATE ,od.PIECES ,od.GWT ,od.CD_TYPE ,od.REMARKS ,od.INSPECTION_YN ,od.INSPECTION_TYPE ,od.AMOUNT_LOC ,od.AMOUNT_CUR ,od.COMMODITY_ITEM ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME ,ad.SE_INSPECTION_YN ,ad.DROP_YN ,ad.XRAY_YN ,CASE WHEN ISNULL(ad.CARRYIN_DATE, '') = '' THEN 'N' ELSE 'Y' END AS CARRYIN_YN ,ad.CARRYIN_DATE ,CASE WHEN ISNULL(ad.CARRYOUT_DATE, '') = '' THEN 'N' ELSE 'Y' END AS CARRYOUT_YN ,ad.CARRYOUT_DATE ,ad.CLEARANCE_YN ,ad.CLEARANCE_DATE ,CASE WHEN ad.DELIVERY_RECV_DATE IS NOT NULL THEN 'Y' ELSE 'N' END AS DELIVERY_RECV_YN ,ad.DELIVERY_RECV_DATE ,CASE WHEN od.CLEARANCE_VIOLATION_CODE IS NOT NULL THEN 'Y' ELSE 'N' END AS CLEARANCE_VIOLATION_YN ,od.CONSIGNEE_NAME_LOC
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND(
(
od.AR_DATE = #{item.srchDate}
1 = 0
AND od.CUST_CODE_LV2 = #{item.srchCustCodeLv2}
AND od.CUST_CODE_LV2 IS NULL
)
)
AND(
(
od.OB_DATE = #{item.srchDate}
1 = 0
AND od.CUST_CODE_LV2 = #{item.srchCustCodeLv2}
AND od.CUST_CODE_LV2 IS NULL
)
)

/* OrderMapper.selectOrderListCus : Order List(고객상담관리) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT cs.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = cs.ENT_CODE AND USER_ID = cs.REGISTER_USER_ID) AS REGISTER_USER_NAME ,cs.REGISTER_DATE_TIME ,cs.CS_TYPE ,cs.CS_CONTENTS ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME ,od.CONSIGNEE_NAME_LOC ,od.AR_DATE ,od.HBL_NO ,od.MBL_NO ,od.VESSEL_FLIGHT ,od.PIECES ,od.GWT ,od.AMOUNT_LOC ,od.COMMODITY_ITEM ,od.INSPECTION_YN ,ad.SE_INSPECTION_YN ,ad.DROP_YN ,CASE WHEN (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0 THEN 'Y' ELSE 'N' END AS HOLD_YN ,od.CD_TYPE ,od.CD_USE_TYPE ,od.ECM_TYPE ,od.CUST_CODE_LV1 ,od.CUST_CODE_LV2 ,od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,(SELECT SUM(AR_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO) AS AR_AMOUNT_SUM ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO) AS AP_AMOUNT_SUM ,COUNT(CASE cs.CS_TYPE WHEN '1' THEN 1 END) OVER() AS CS_TYPE1_CNT ,COUNT(CASE cs.CS_TYPE WHEN '2' THEN 1 END) OVER() AS CS_TYPE2_CNT ,COUNT(CASE cs.CS_TYPE WHEN '3' THEN 1 END) OVER() AS CS_TYPE3_CNT ,COUNT(CASE cs.CS_TYPE WHEN '4' THEN 1 END) OVER() AS CS_TYPE4_CNT ,COUNT(CASE cs.CS_TYPE WHEN '5' THEN 1 END) OVER() AS CS_TYPE5_CNT ,COUNT(CASE cs.CS_TYPE WHEN '6' THEN 1 END) OVER() AS CS_TYPE6_CNT ,CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE ENT_CODE = od.ENT_CODE AND FUNC_JOB_NO = od.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL
FROM TB_SMS_CS cs INNER JOIN TB_ECM_OD od ON od.OD_JOB_NO = cs.REF_JOB_NO INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO

/* OrderMapper.selectOrderListCusCost : Order List(추가비용) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT cst.AR_INVOICE_DATE ,cst.AP_INVOICE_DATE ,cst.CHARGE_CODE ,cst.CHARGE_NAME ,cst.ACCOUNT_CODE ,cst.ACCOUNT_NAME ,cst.AR_AMOUNT ,cst.AR_AMOUNT_CUR ,cst.AP_AMOUNT ,cst.CURRENCY_CODE ,cst.REMARKS ,cst.PAYMENT_GUBN ,cst.CUSTOMER_CODE ,cst.CUSTOMER_NAME ,cst.PAYMENT_DATE ,cst.SEQ_NO_ID ,cst.AR_INVOICE_JOB_NO ,cst.AP_INVOICE_JOB_NO ,cst.OD_JOB_NO ,cst.REGISTER_USER_ID ,CONVERT(VARCHAR(16), cst.REGISTER_DATE_TIME, 20) AS REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = cst.REGISTER_USER_ID) AS REGISTER_USER_NAME
,chg.CHG_CODE_SYSTEM AS CHG_TYPE FROM TB_ECM_OD_COST cst INNER JOIN TB_SMS_CHARGE chg ON chg.ENT_CODE = #{srchEntCode} AND chg.CHARGE_CODE = cst.CHARGE_CODE
AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{srchChgType}, '%')
FROM TB_ECM_OD_COST cst
WHERE cst.OD_JOB_NO = #{srchOdJobNo}

mapper.update:
/* OrderMapper.updateCostInfo : 오더추가비용정보 업데이트 */
	UPDATE TB_ECM_OD SET
		   UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())




		  ,CLEARANCE_PAYMENT_TYPE = #{clearancePaymentType}


		  ,CB_CODE = #{cbCode}





		  ,DELIVERY_PAYMENT_TYPE = #{deliveryPaymentType}


		  ,DELIVERY_CODE = #{deliveryCode}

	WHERE OD_JOB_NO = #{odJobNo}

/* OrderMapper.updateConsigneeZipCode : 전자상거래 Order 수화인우편번호변환 */
