	WHERE OD_JOB_NO = #{odJobNo}

/* OrderMapper.updateOrderLastPod : 전자상거래 Order 상태업데이트 */


	UPDATE TB_ECM_OD_ADDITIONAL SET


		   LAST_POD_STATUS = LAST_POD_STATUS

		  ,DELIVERY_STATUS = #{podStatus}


		   LAST_POD_STATUS = #{podStatus}



	WHERE OD_JOB_NO = #{odJobNo}

	AND ISNULL(LAST_POD_STATUS, '') < #{podStatus}



	UPDATE ad SET 
		   ad.LAST_POD_STATUS = #{podStatus}

	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	WHERE od.ENT_CODE = #{entCode}
	AND od.HBL_NO = LTRIM(RTRIM(#{HBL_NO}))
	AND ISNULL(ad.LAST_POD_STATUS, '') < #{podStatus}


		AND od.MBL_NO = LTRIM(RTRIM(#{MBL_NO}))


		AND (od.MBL_NO = '' OR od.MBL_NO IS NULL)

