AND od.OD_JOB_NO = #{odJobNo}
AND od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
AND od.MBL_NO = LTRIM(RTRIM(#{MBL_NO}))
AND (od.MBL_NO = '' OR od.MBL_NO IS NULL)
UNION ALL SELECT od.OD_JOB_NO ,pod.POD_JOB_NO FROM TB_ECM_OD od LEFT JOIN TB_ECM_POD_01 pod ON pod.OD_JOB_NO = od.OD_JOB_NO AND pod.POD_STATUS = #{podStatus} WHERE od.ENT_CODE = #{entCode}
AND od.OD_JOB_NO = #{odJobNo}
AND od.HBL_NO = LTRIM(RTRIM(#{hblNo}))
AND od.MBL_NO = LTRIM(RTRIM(#{MBL_NO}))
