mapper.select:
/* OrderMapper.selectCombinedTaxParams : 합산과세대상조회 */
WITH TMP AS( SELECT
od.CONSIGNEE_ADDRESS, od.CONSIGNEE_ADDRESS_A, od.CONSIGNEE_ADDRESS_B, od.CONSIGNEE_ADDRESS_C, od.CONSIGNEE_ADDRESS_D
dbo.Cryptography(od.OD_JOB_NO, ${srchTaxType}_ENC, 1) AS ${srchTaxType2}
${srchTaxType}
,od.OD_JOB_NO ,od.AMOUNT_USD ,od.ORIG_COUNTRY ,od.AR_DATE
FROM TB_ECM_OD od WHERE od.ENT_CODE = #{srchEntCode} AND od.BOUND = #{srchBound} AND od.BOUND_TYPE = 'IMP' AND od.BL_TYPE_MH = 'H' AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})) AND ISNULL(AMOUNT_USD ,0) > 0
AND od.CUST_CODE_LV${level} = #{srchEcmCustomerCode}
AND od.CONSOL_YN =#{srchConsolYn}
AND (ISNULL(od.CONSIGNEE_ADDRESS,'') != '' OR ISNULL(od.CONSIGNEE_ADDRESS_A,'') != '' OR ISNULL(od.CONSIGNEE_ADDRESS_B,'') != '' OR ISNULL(od.CONSIGNEE_ADDRESS_C,'') != '' OR ISNULL(od.CONSIGNEE_ADDRESS_D,'') != '')
AND dbo.Cryptography(od.OD_JOB_NO, ${srchTaxType}_ENC, 1) != ''
AND ISNULL(${srchTaxType},'') != ''
AND od.CD_TYPE = 'Y'
)
SELECT STUFF((SELECT ',' + OD_JOB_NO FROM TMP WHERE
CONSIGNEE_ADDRESS = t.CONSIGNEE_ADDRESS AND CONSIGNEE_ADDRESS_A = t.CONSIGNEE_ADDRESS_A AND CONSIGNEE_ADDRESS_B = t.CONSIGNEE_ADDRESS_B AND CONSIGNEE_ADDRESS_C = t.CONSIGNEE_ADDRESS_C AND CONSIGNEE_ADDRESS_D = t.CONSIGNEE_ADDRESS_D
${srchTaxType2} = t.${srchTaxType2}
and AR_DATE = t.AR_DATE FOR XML PATH('')), 1, 1, '') AS OD_JOB_NO FROM TMP t GROUP BY
t.CONSIGNEE_ADDRESS, t.CONSIGNEE_ADDRESS_A, t.CONSIGNEE_ADDRESS_B, t.CONSIGNEE_ADDRESS_C, t.CONSIGNEE_ADDRESS_D
${srchTaxType2}
,AR_DATE
HAVING count(*) > 1 AND (((MAX(t.ORIG_COUNTRY) = 'US' OR MAX(t.ORIG_COUNTRY) = 'PR') AND SUM(t.AMOUNT_USD) > 200) OR (MAX(t.ORIG_COUNTRY) != 'US' AND MAX(t.ORIG_COUNTRY) != 'PR' AND SUM(t.AMOUNT_USD) > 150))

