	WHERE OD_JOB_NO IN (#{item})

/* OrderMapper.updateExcelUploadCarryin : Order List(Detail) - 반입근거번호 수정 */
	UPDATE TB_ECM_OD 
	SET CARRYIN_NO = #{CARRYIN_NO}
	,UPDATE_USER_ID = #{updateUserId}
	,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE ENT_CODE = #{entCode}
	AND BOUND = #{bound}
	AND BOUND_TYPE = #{boundType}
	AND MBL_NO = LTRIM(RTRIM(REPLACE(#{MBL_NO},char(9),'')))
	AND HSN >= #{HSN_STRT} AND HSN <= #{HSN_END}

/* OrderMapper.updateOrderAdditionalBatchBySrchData : Order Additional List 일괄변경 */ UPDATE ad SET ${updateField} = #{updateValue}
,STOCK_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,STOCK_USER_ID = #{updateUserId} ,STOCK_YN = 'Y' ,CARRYOUT_DATE = NULL ,CARRYOUT_USER_ID = NULL
,${updateField2} = #{updateValue2}
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_HOLD hld ON hld.OD_JOB_NO = od.OD_JOB_NO

/* OrderMapper.updateOrderAdditionalBatch : Order Additional List 일괄변경 */ UPDATE ad SET ad.${updateField} = #{updateValue}
,ad.STOCK_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,ad.STOCK_USER_ID = #{updateUserId} ,ad.STOCK_YN = 'Y' ,ad.CARRYOUT_DATE = NULL ,ad.CARRYOUT_USER_ID = NULL
,ad.${updateField2} = #{updateValue2}
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE (
(od.MASTER_OD_JOB_NO = #{item.odJobNo} AND ISNULL(ad.SIMPLE_DOC_NO, '') = ISNULL(CAST(#{item.simpleDocNo} AS VARCHAR(20)), ''))
)
WHERE od.MASTER_OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H'
WHERE od.OD_JOB_NO IN(#{item})

