mapper.select:
/* OrderMapper.selectOdJobNoByBlNo : 비엘번호로 오더관리번호조회 */ SELECT OD_JOB_NO FROM TB_ECM_OD WHERE ENT_CODE = #{entCode} AND HBL_NO = LTRIM(RTRIM(#{HBL_NO}))
AND MBL_NO = LTRIM(RTRIM(#{MBL_NO}))
AND (MBL_NO = '' OR MBL_NO IS NULL)

/* OrderMapper.selectMasterInfo : 마스터정보조회 */ SELECT od.FINISH_YN ,od.CONSOL_YN ,od.OD_JOB_NO
,ad.SIMPLE_EDI_STATUS
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.OD_JOB_NO = #{masterOdJobNo}

/* OrderMapper.selectOrderByBlNo : 비엘번호로 오더조회 */
	SELECT OD_JOB_NO
	FROM TB_ECM_OD
	WHERE ENT_CODE = #{entCode}
	AND BL_TYPE_MH = #{blTypeMh}


	AND MBL_NO = LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))


	AND HBL_NO = LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))



	AND OD_JOB_NO != #{odJobNo}


	AND OD_JOB_NO NOT IN(#{item})


	AND BOUND = #{bound}
	AND BOUND_TYPE = #{boundType}

