/* OrderMapper.deleteCost : Order 추가비용 Delete */


	DELETE FROM cost
	FROM TB_ECM_OD_COST cost
		 INNER JOIN TB_SMS_CHARGE chg
		 			ON chg.ENT_CODE = #{entCode}
		 			AND chg.CHARGE_CODE = cost.CHARGE_CODE
		 			AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{updateType}, '%')
	WHERE cost.OD_JOB_NO = #{odJobNo}


	DELETE TB_ECM_OD_COST
	WHERE OD_JOB_NO = #{odJobNo}



	AND SEQ_NO_ID IN(#{item.seqNoId})

/* OrderMapper.deleteOdChgInv : Order 일반정산 Delete */


	DELETE FROM cost
	FROM TB_ECM_OD_CHG_INVOICE chgInv
		 INNER JOIN TB_SMS_CHARGE chg
		 			ON chg.ENT_CODE = #{entCode}
		 			AND chg.CHARGE_CODE = chgInv.CHARGE_CODE
		 			AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{updateType}, '%')
	WHERE chgInv.OD_JOB_NO = #{odJobNo}


	DELETE TB_ECM_OD_CHG_INVOICE
	WHERE OD_JOB_NO = #{odJobNo}

