/* OrderMapper.selectMulti : Order 멀티(중량)화물 조회 */ SELECT mti.DELIVERY_NO ,mti.DELIVERY_CODE ,mti.CUSTOMER_CODE ,mti.DELIVERY_NO_CHANGED ,mti.PAYMENT_GUBN ,mti.DELIVERY_FEE ,mti.PIECES ,mti.DIM_WIDTH ,mti.DIM_LENGTH ,mti.DIM_HEIGHT ,mti.VWT ,mti.RECIPIENT_NAME ,mti.SEQ_NO_ID ,CONVERT(VARCHAR(10), mti.RECEIPT_DATE, ${dateFormat}) AS RECEIPT_DATE ,mti.REMARKS ,mti.REGISTER_USER_ID ,CONVERT(VARCHAR(16), mti.REGISTER_DATE_TIME, 20) AS REGISTER_DATE_TIME ,mti.DELIVERER_USER_ID ,CONVERT(VARCHAR(10), mti.DELIVERY_DATE, ${dateFormat}) AS DELIVERY_DATE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE = mti.CUSTOMER_CODE) AS CUSTOMER_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = mti.REGISTER_USER_ID) AS REGISTER_USER_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = #{srchEntCode} AND USER_ID = mti.DELIVERER_USER_ID) AS DELIVERER_USER_NAME
,mti.RETURN_DELIVERY_NO ,mti.RETURN_REQUEST_ID ,CONVERT(VARCHAR(10), mti.RETURN_REQ_DATE, ${dateFormat}) AS RETURN_REQ_DATE ,ISNULL(mti.RETURN_DELIVERY_CODE,'') AS RETURN_DELIVERY_CODE ,CONVERT(VARCHAR(10), mti.RETURN_END_DATE, ${dateFormat}) AS RETURN_END_DATE ,CONVERT(VARCHAR(10), mti.RETURN_REG_DATE, ${dateFormat}) AS RETURN_REG_DATE ,CONVERT(VARCHAR(10), mti.RETURN_DLV_REQ_DATE, ${dateFormat}) AS RETURN_DLV_REQ_DATE ,CONVERT(VARCHAR(10), mti.DELIVERY_REG_DATE, ${dateFormat}) AS DELIVERY_REG_DATE ,CONVERT(VARCHAR(10), mti.DELIVERY_END_DATE, ${dateFormat}) AS DELIVERY_END_DATE ,mti.CONSIGNEE_NAME_LOC_M ,mti.CONSIGNEE_ADDRESS_LOC_M ,mti.CONSIGNEE_TEL_M ,mti.CONSIGNEE_ZIPCODE_M ,mti.RETURN_DELIVERY_STATUS
FROM TB_ECM_OD_MULTI mti WHERE mti.OD_JOB_NO = #{srchOdJobNo} ORDER BY mti.SEQ_NO_ID

