		,cs.CS_TYPE
		,cs.CS_CONTENTS
		,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cs.ENT_CODE AND GROUP_CODE = 'CS_TYPE' AND CODE = cs.CS_TYPE) AS CS_TYPE_NAME
		,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = cs.ENT_CODE AND USER_ID = cs.REGISTER_USER_ID) AS REGISTER_USER_NAME
		,cs.REGISTER_DATE_TIME
	FROM TB_SMS_CS cs
	WHERE ENT_CODE = #{entCode}


	AND REF_JOB_NO = #{refJobNo}


	AND SEQ_NO_ID = #{seqNoId}

