/* OrderMapper.updateItemExcelError : 오더 엑셀업로드 오류내역 수정 세부품목에 반영되어야 할 내용 업데이트 */
	UPDATE TB_ECM_OD_ITEM SET
		   OD_JOB_NO = #{odJobNo}

		  ,HS_CODE = CASE WHEN ISNULL(HS_CODE, '') = '' THEN #{allowedItemCode} ELSE HS_CODE END


		  ,CURRENCY_CODE = CASE WHEN ISNULL(CURRENCY_CODE, '') = '' THEN #{currencyCode} ELSE CURRENCY_CODE END


		  ,GWT = GWT * 0.45359237

	WHERE OD_JOB_NO = #{odJobNo}

