	UPDATE TB_ECM_POD SET BL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD_01 SET BL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD_02 SET BL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD_03 SET BL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_POD_04 SET BL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};

