/* OrderMapper.selectOrderPodStatusList : 오더 pod조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SELECT od.OD_JOB_NO ,pod.POD_STATUS ,CASE WHEN LEN(ISNULL(pod.POD_TIME, '')) = 5 THEN CONCAT(ISNULL(pod.POD_DATE, '1900-01-01'), ' ', pod.POD_TIME, ':01') ELSE CONCAT(ISNULL(pod.POD_DATE, '1900-01-01'), ' ', ISNULL(pod.POD_TIME, '00:00:00')) END AS POD_DATE_TIME ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = pod.POD_STATUS) AS POD_STATUS_NAME ,pod.COURIER_NAME ,pod.REGISTER_USER_ID ,usr.USER_LOGIN_ID ,usr.USER_NAME AS REGISTER_USER_NAME ,od.HBL_NO ,od.MBL_NO ,ISNULL(od.PIECES,0) AS PIECES ,ISNULL(od.PIECES_REAL,0) AS PIECES_REAL ,ISNULL(od.GWT,0) AS GWT ,od.CONSIGNEE_NAME_LOC ,od.COMMODITY_ITEM ,CASE WHEN NULLIF(od.MRN, '') IS NULL THEN NULL ELSE CASE WHEN NULLIF(od.MSN, '') IS NOT NULL AND NULLIF(od.HSN, '') IS NOT NULL THEN CONCAT(od.MRN, '-', od.MSN, '-', od.HSN) WHEN NULLIF(od.MSN, '') IS NOT NULL THEN CONCAT(od.MRN, '-', od.MSN) ELSE od.MRN END END AS SHIPMENT_NO ,od.BOUND ,od.BOUND_TYPE ,pod.REMARKS FROM TB_ECM_OD od INNER JOIN ( SELECT #{srchOdJobNo} AS OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, COURIER_NAME, REGISTER_USER_ID, REMARKS FROM TB_ECM_POD WHERE OD_JOB_NO = (SELECT MASTER_OD_JOB_NO FROM TB_ECM_OD WHERE OD_JOB_NO = #{srchOdJobNo}) AND POD_STATUS IN ('ECM060','ECM070') UNION ALL SELECT #{srchOdJobNo} AS OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, '' AS COURIER_NAME, REGISTER_USER_ID, '' AS REMARKS FROM TB_ECM_POD_01 WHERE OD_JOB_NO = (SELECT MASTER_OD_JOB_NO FROM TB_ECM_OD WHERE OD_JOB_NO = #{srchOdJobNo}) AND POD_STATUS IN ('ECM060','ECM070') UNION ALL SELECT OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, COURIER_NAME, REGISTER_USER_ID, REMARKS FROM TB_ECM_POD WHERE OD_JOB_NO = #{srchOdJobNo} AND POD_STATUS NOT IN ('ECM060','ECM070') UNION ALL SELECT OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, '' AS COURIER_NAME, REGISTER_USER_ID, '' AS REMARKS FROM TB_ECM_POD_01 WHERE OD_JOB_NO = #{srchOdJobNo} AND POD_STATUS NOT IN ('ECM060','ECM070') UNION ALL SELECT OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, '' AS COURIER_NAME, REGISTER_USER_ID, '' AS REMARKS FROM TB_ECM_POD_02 WHERE OD_JOB_NO = #{srchOdJobNo} UNION ALL SELECT OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, '' AS COURIER_NAME, REGISTER_USER_ID, REMARKS FROM TB_ECM_POD_03 WHERE OD_JOB_NO = #{srchOdJobNo} UNION ALL SELECT OD_JOB_NO, POD_STATUS, POD_DATE, POD_TIME, COURIER_NAME, REGISTER_USER_ID, REMARKS FROM TB_ECM_POD_04 WHERE OD_JOB_NO = #{srchOdJobNo} ) pod ON pod.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_SMS_USER usr ON usr.ENT_CODE = od.ENT_CODE AND usr.USER_ID = pod.REGISTER_USER_ID WHERE od.ENT_CODE = #{srchEntCode} AND od.OD_JOB_NO = #{srchOdJobNo}
UNION ALL
SELECT pod5.OD_JOB_NO ,pod5.POD_STATUS ,CONCAT(ISNULL(pod5.POD_DATE, '1900-01-01'), ' ', ISNULL(pod5.POD_TIME, '00:00:00')) AS POD_DATE_TIME ,pod5.POD_NAME AS POD_STATUS_NAME ,NULL AS COURIER_NAME ,pod5.REGISTER_USER_ID ,(SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE USER_ID = pod5.REGISTER_USER_ID) AS USER_LOGIN_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = pod5.REGISTER_USER_ID) AS REGISTER_USER_NAME ,'' AS HBL_NO ,'' AS MBL_NO ,0 AS PIECES ,0 AS PIECES_REAL ,0 AS GWT ,'' AS CONSIGNEE_NAME_LOC ,'' AS COMMODITY_ITEM ,'' AS SHIPMENT_NO ,'' AS BOUND ,'' AS BOUND_TYPE ,pod5.REMARKS FROM TB_ECM_POD_05 pod5 WHERE OD_JOB_NO = #{srchOdJobNo}
ORDER BY POD_DATE_TIME DESC, pod.POD_STATUS DESC

