/* OrderMapper.selectSimpleDocNoCnt : 마스터의제출번호건수조회 */ SELECT od.OD_JOB_NO ,( SELECT COUNT(hod.OD_JOB_NO) FROM TB_ECM_OD hod INNER JOIN TB_ECM_OD_ADDITIONAL had ON had.OD_JOB_NO = hod.OD_JOB_NO AND had.SIMPLE_DOC_NO = ad.SIMPLE_DOC_NO WHERE hod.MASTER_OD_JOB_NO = od.OD_JOB_NO AND hod.BL_TYPE_MH = 'H' ) AS HOUSE_COUNT FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.OD_JOB_NO = #{masterOdJobNo}
AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
AND ad.SIMPLE_DOC_NO IN(#{item})

/* OrderMapper.selectCarryinList : carryinNo 변경 리스트 조회 */	
SELECT od.OD_JOB_NO, MBL_NO, HBL_NO, BOUND, BOUND_TYPE
FROM TB_ECM_OD od
WHERE  MBL_NO = LTRIM(RTRIM(REPLACE(#{MBL_NO},char(9),'')))
AND HSN >= #{HSN_STRT} AND HSN <= #{HSN_END}

/* OrderMapper.selectOrderGwtPieces : Order 조회 (수량,중량) */
	SELECT
		 od.MASTER_OD_JOB_NO 
		,SUM(od.gwt) GWT
		,SUM(od.PIECES) PIECES
		,SUM(PIECES_REAL) PIECES_REAL
	FROM TB_ECM_OD od
	WHERE od.ENT_CODE = #{srchEntCode}
	AND od.MASTER_OD_JOB_NO = #{srchOdJobNo}
	AND od.BL_TYPE_MH = #{srchBlTypeMh}
	GROUP BY MASTER_OD_JOB_NO;

