/* OrderMapper.selectOrderListCSum : Order List(통관목록현황집계) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT COUNT(CASE WHEN od.CD_TYPE = 'Y' THEN code ELSE NULL END) AS TOT_CNT , COUNT(CASE WHEN od.CD_TYPE = 'N' THEN code ELSE NULL END) AS TOT_CNT_N , COUNT(CASE WHEN od.CD_TYPE = 'B' THEN code ELSE NULL END) AS CNT , SUBSTRING(od.HBL_NO, 1, 6) AS HBL_NO , MAX(ETC2) AS Code , MAX(mod.OB_DATE) AS OB_DATE , MAX(mod.AR_DATE) AS AR_DATE FROM TB_ECM_OD od LEFT JOIN TB_SMS_CODE_DETAIL det ON det.GROUP_CODE = 'CLS_FILTER_CODE' AND det.CODE = SUBSTRING(od.HBL_NO, 1, 6) LEFT JOIN TB_ECM_OD mod ON mod.OD_JOB_NO = od.MASTER_OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND ${srchDateGbn} BETWEEN #{srchStartDate} AND #{srchEndDate}
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
GROUP BY SUBSTRING(od.HBL_NO, 1, 6)

/* OrderMapper.selectOrderMasterDupList : 중복HAWB조회 - Master List 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT MBL_NO , OD_JOB_NO , AR_DATE , (SELECT COUNT(HBL_NO) FROM TB_ECM_OD WHERE ENT_CODE = od.ENT_CODE AND MASTER_OD_JOB_NO = od.OD_JOB_NO AND BL_TYPE_MH = 'H') AS HBL_CNT , VESSEL_FLIGHT , ORIG_CODE , DEST_CODE FROM TB_ECM_OD od
AND od.ENT_BUSINESS_CODE = #{srchEntBusinessCode}

/* OrderMapper.selectClsFilterCodeDupCheck : Order List(통관목록현황집계) 필터 코드 중복 체크 */
