/* OrderMapper.selectOrderHouseDupList : 중복HAWB조회 - 중복 House List 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT MBL_NO , HSN , HBL_NO , AR_DATE , PIECES , GWT , CONSIGNEE_NAME , REGISTER_DATE_TIME , OD_JOB_NO , NEW_YN FROM ( SELECT MBL_NO , HSN , od.HBL_NO , AR_DATE , PIECES , GWT , CONSIGNEE_NAME , CONVERT(CHAR(19), REGISTER_DATE_TIME, 20) AS REGISTER_DATE_TIME , OD_JOB_NO , CASE WHEN od.MASTER_OD_JOB_NO = srchOd.MASTER_OD_JOB_NO THEN '신규' ELSE NULL END AS NEW_YN , COUNT(*) OVER(PARTITION BY od.HBL_NO) AS CNT FROM TB_ECM_OD od INNER JOIN ( SELECT HBL_NO, MASTER_OD_JOB_NO FROM TB_ECM_OD WHERE MASTER_OD_JOB_NO = #{srchMasterOdJobNo} AND BL_TYPE_MH = 'H' ) srchOd ON od.HBL_NO = srchOd.HBL_NO WHERE ENT_CODE = #{srchEntCode} AND SOLUTION = #{srchSolution} AND BL_TYPE_MH = 'H' AND AR_DATE >= CONVERT(DATE, #{srchStartDate}, 23) AND AR_DATE <= CONVERT(DATE, #{srchEndDate}, 23)
AND BOUND = 'AIR' AND BOUND_TYPE = 'IMP' AND BOUND = 'SEA' AND BOUND_TYPE = 'IMP'
) TMP WHERE CNT > 1
AND ISNULL(NEW_YN, '') != ''

