/* OrderMapper.updateOrderSelectorBatchBySrchData : Order List(Detail) - 선별자 일괄변경 */
	UPDATE od SET
		    UPDATE_USER_ID = #{updateUserId}
			,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

			,SELECTOR_USER_ID = #{selectorUserId}


			,SELECTOR_USER_NAME = #{selectorUserName}


			,CONFIRMER_USER_ID = #{confirmerUserId}


			,CONFIRMER_USER_NAME = #{confirmerUserName}


			,XRAY_READER1_NAME = #{xrayReader1Name}


			,XRAY_READER2_NAME = #{xrayReader2Name}

	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO

/* OrderMapper.updateOrderBatch : Order List(Detail) - 일괄변경 */
	UPDATE od SET
		   od.UPDATE_USER_ID = #{updateUserId}
		   ,od.UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

			,od.SELECTOR_USER_ID = #{selectorUserId}


			,od.SELECTOR_USER_NAME = #{selectorUserName}


			,od.CONFIRMER_USER_ID = #{confirmerUserId}


			,od.CONFIRMER_USER_NAME = #{confirmerUserName}


			,od.XRAY_READER1_NAME = #{xrayReader1Name}


			,od.XRAY_READER2_NAME = #{xrayReader2Name}

	FROM TB_ECM_OD od




			 INNER JOIN TB_ECM_OD_ADDITIONAL ad
			 			ON ad.OD_JOB_NO = od.OD_JOB_NO
		WHERE (

			(od.MASTER_OD_JOB_NO = #{item.odJobNo} AND ISNULL(ad.SIMPLE_DOC_NO, '') = ISNULL(CAST(#{item.simpleDocNo} AS VARCHAR(20)), ''))

		)


		WHERE od.MASTER_OD_JOB_NO IN(#{item})


	AND od.BL_TYPE_MH = 'H'


	WHERE od.OD_JOB_NO IN(#{item})

