/* OrderMapper.selectOrderListDet : Order List(KREAM 수출통관용 엑셀 오더정보) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.ENT_CODE ,od.ENT_BUSINESS_CODE ,od.OD_JOB_NO
,od.PO_NO ,od.HBL_NO ,od.GWT ,CASE WHEN ISNULL(item.DETAIL_ITEM_NAME_LOC, '') != '' THEN item.DETAIL_ITEM_NAME_LOC ELSE item.DETAIL_ITEM_NAME END AS COMMODITY_ITEM ,item.PIECES ,item.UNIT_PRICE ,od.CURRENCY_CODE
,1 AS CNT ,od.CBM ,item.HS_CODE ,ROUND((CASE WHEN od.BOUND = 'SEA' THEN CASE WHEN od.GWT <= 0.5 THEN 4900 WHEN od.GWT > 0.5 AND od.GWT <= 1.0 THEN 5800 WHEN od.GWT > 1.0 AND od.GWT <= 1.5 THEN 6700 WHEN od.GWT > 1.5 AND od.GWT <= 2.0 THEN 7500 WHEN od.GWT > 2.0 AND od.GWT <= 2.5 THEN 8400 WHEN od.GWT > 2.5 AND od.GWT <= 3.0 THEN 9300 WHEN od.GWT > 3.0 AND od.GWT <= 3.5 THEN 10100 WHEN od.GWT > 3.5 AND od.GWT <= 4.0 THEN 11000 WHEN od.GWT > 4.0 AND od.GWT <= 4.5 THEN 11900 WHEN od.GWT > 4.5 THEN 12800 END ELSE CASE WHEN od.GWT <= 0.5 THEN 5000 WHEN od.GWT > 0.5 AND od.GWT <= 1.0 THEN 6200 WHEN od.GWT > 1.0 AND od.GWT <= 1.5 THEN 7400 WHEN od.GWT > 1.5 AND od.GWT <= 2.0 THEN 8700 WHEN od.GWT > 2.0 AND od.GWT <= 2.5 THEN 9900 WHEN od.GWT > 2.5 AND od.GWT <= 3.0 THEN 11100 WHEN od.GWT > 3.0 AND od.GWT <= 3.5 THEN 12300 WHEN od.GWT > 3.5 AND od.GWT <= 4.0 THEN 13600 WHEN od.GWT > 4.0 AND od.GWT <= 4.5 THEN 14800 WHEN od.GWT > 4.5 THEN 16000 END END + (item.AMOUNT) + (item.AMOUNT * 0.0385 + 5500) ) * #{exchangeRateUsd} , 2) AS TOTAL_AMOUNT
,'DDU' AS DUTY ,ROUND((item.AMOUNT * #{exchangeRateUsd} / #{exchangeRateJpy} ), 0) AS INV_VALUE ,od.SHIPPER_NAME ,od.SHIPPER_ADDRESS ,od.SHIPPER_TEL ,'KRICN' AS DEST_CODE
FROM TB_ECM_OD od LEFT OUTER JOIN TB_ECM_OD_ITEM item ON item.OD_JOB_NO = od.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO IN (#{item})
AND od.ORIG_COUNTRY = #{srchOrigCountry}

/* OrderMapper.selectOrderDashboardList : 대시보드 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; WITH OD_LIST AS ( SELECT od.ENT_CODE , od.OD_JOB_NO , ad.LAST_POD_STATUS , ISNULL(od.ORIG_COUNTRY,'') AS ORIG_COUNTRY , od.PO_DATE , ad.DELIVERY_DATE , ad.CARRYIN_DATE , ad.CARRYOUT_DATE , ad.UNUSUAL_CODE , od.BOUND_TYPE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.PO_DATE >= CONVERT(VARCHAR(10), DATEADD(DAY , (CASE WHEN #{srchDateType} = '7' THEN -7 WHEN #{srchDateType} = '14' THEN -14 WHEN #{srchDateType} = '30' THEN -30 ELSE -7 END), GETDATE()) , 23) AND od.PO_DATE < CONVERT(VARCHAR(10), DATEADD(DAY , (CASE WHEN #{srchDateType} = '7' THEN 7 WHEN #{srchDateType} = '14' THEN 14 WHEN #{srchDateType} = '30' THEN 30 ELSE 7 END), GETDATE()) , 23)
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
), DIFF AS ( SELECT ORIG_COUNTRY AS COUNTRY , ROUND(AVG(DATEDIFF(DAY, CARRYIN_DATE, DELIVERY_DATE) * 1.0), 1) AS DIFF FROM OD_LIST D_LIST WHERE LAST_POD_STATUS IN ('ECM420', 'ECM423', 'ECM424') GROUP BY ORIG_COUNTRY ) SELECT 'pod' AS DASHBOARD_TYPE, CODE, '' AS NAME, COUNT, 0 AS COUNT2 FROM ( SELECT 'ECM010' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM010' UNION ALL SELECT 'ECM050' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM050' UNION ALL SELECT 'ECM040' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM040' UNION ALL SELECT 'ECM060' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM060' UNION ALL SELECT 'ECM100' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS IN ('ECM070','ECM100','ECM110','ECM115','ECM120','ECM130','ECM140','ECM150') UNION ALL SELECT 'ECM160' AS CODE, MAX(CASE WHEN SUB_CODE = 'ECM160' THEN COUNT ELSE 0 END) + MAX(CASE WHEN SUB_CODE = 'ECM100' THEN COUNT ELSE 0 END) AS COUNT FROM ( SELECT 'ECM160'AS SUB_CODE, COUNT(od.OD_JOB_NO) AS COUNT FROM OD_LIST od INNER JOIN TB_ECM_OD_ABNORMAL ab ON ab.OD_JOB_NO = od.OD_JOB_NO AND ab.ABNORMAL_CODE = 'MGN' WHERE od.LAST_POD_STATUS = 'ECM160' UNION ALL SELECT 'ECM100'AS SUB_CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS IN ('ECM070','ECM100','ECM110','ECM115','ECM120','ECM130','ECM140','ECM150') ) AS OD_SUB UNION ALL SELECT 'ECM210' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE 1=1 AND (LAST_POD_STATUS = 'ECM210' OR (LAST_POD_STATUS IN ('ECM250','ECM260','ECM270','ECM251') AND CARRYIN_DATE IS NOT NULL)) UNION ALL SELECT 'ECM280' AS CODE, MAX(CASE WHEN SUB_CODE = 'ECM280' THEN COUNT ELSE 0 END) + MAX(CASE WHEN SUB_CODE = 'ECM210' THEN COUNT ELSE 0 END) AS COUNT FROM ( SELECT 'ECM280' AS SUB_CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM280' AND ISNULL(CARRYOUT_DATE, '') = '' UNION ALL SELECT 'ECM210' AS SUB_CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE 1=1 AND (LAST_POD_STATUS = 'ECM210' OR (LAST_POD_STATUS IN ('ECM250','ECM260','ECM270','ECM251') AND CARRYIN_DATE IS NOT NULL)) ) AS OD_SUB UNION ALL SELECT 'ECM250' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS IN ('ECM250','ECM260','ECM270','ECM251') UNION ALL SELECT 'ECM290' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM290' UNION ALL SELECT 'ECM400' AS CODE, MAX(CASE WHEN SUB_CODE = 'ECM400' THEN COUNT ELSE 0 END) + MAX(CASE WHEN SUB_CODE = 'ECM290' THEN COUNT ELSE 0 END) AS COUNT FROM ( SELECT 'ECM400' AS SUB_CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS IN ('ECM400','ECM410','ECM390','ECM380','ECM370','ECM361') UNION ALL SELECT 'ECM290' AS SUB_CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM290' ) AS OD_SUB UNION ALL SELECT 'ECM420' AS CODE, COUNT(OD_JOB_NO) AS COUNT FROM OD_LIST WHERE LAST_POD_STATUS = 'ECM420' ) od UNION ALL SELECT 'country' AS DASHBOARD_TYPE , ISNULL(CODE, '') AS CODE , CAST(CNT AS VARCHAR(50)) AS NAME , ISNULL(COUNTRY_DIFF,0) AS COUNT , CASE WHEN SUM_TMP = 0 THEN 0 ELSE ROUND((CAST(SUM_TMP AS FLOAT)/CAST(OD_CNT AS INTEGER)) * 100,0) END AS COUNT2 FROM( SELECT CODE , COUNT(OD_JOB_NO) CNT , MAX(COUNTRY_DIFF) AS COUNTRY_DIFF , SUM(CASE WHEN LAST_POD_STATUS IN ('ECM420', 'ECM423', 'ECM424') AND COUNTRY_DIFF >= DIFF THEN 1 ELSE 0 END) SUM_TMP , SUM(CASE WHEN LAST_POD_STATUS IN ('ECM420', 'ECM423', 'ECM424') THEN 1 ELSE 0 END) OD_CNT FROM ( SELECT OD_JOB_NO , LAST_POD_STATUS , (SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL TSCD WHERE GROUP_CODE = 'COUNTRY' AND CODE = ORIG_COUNTRY) AS CODE , DATEDIFF(DAY, CARRYIN_DATE, DELIVERY_DATE) AS DIFF , DIFF.DIFF AS COUNTRY_DIFF FROM OD_LIST OD LEFT OUTER JOIN DIFF ON DIFF.COUNTRY = od.ORIG_COUNTRY ) od_diff GROUP BY CODE ) od_diff
UNION ALL SELECT 'unusual' AS DASHBOARD_TYPE , '' AS CODE , '' AS NAME , COUNT(*) AS COUNT , 0 AS COUNT2 FROM( SELECT UNUSUAL_CODE FROM OD_LIST WHERE BOUND_TYPE = 'IMP' AND UNUSUAL_CODE IS NOT NULL ) unusual

/* OrderMapper.selectOrderDashboardDiff : Order 대시보드 DIFF */ SELECT 'diff' AS DASHBOARD_TYPE , '' AS CODE , CAST(FORMAT(SUM(IS_THIS_WEEK) - SUM(IS_LAST_WEEK), 'N0') AS VARCHAR(50)) AS NAME , SUM(IS_THIS_MONTH) - SUM(IS_LAST_MONTH) AS COUNT , SUM(IS_THIS_QUARTER) - SUM(IS_LAST_QUARTER) AS COUNT2 FROM ( SELECT
CASE WHEN od.AR_DATE >= CONVERT(VARCHAR(10), DATEADD(DAY, 7-(DATEPART(WEEKDAY, GETDATE())-1)-7, GETDATE()), 23) AND od.AR_DATE < CONVERT(VARCHAR(10), DATEADD(DAY, 7-(DATEPART(WEEKDAY, GETDATE())), GETDATE()), 23) THEN 1 ELSE 0 END AS IS_THIS_WEEK,
CASE WHEN od.AR_DATE >= CONVERT(VARCHAR(10), DATEADD(DAY, 7-(DATEPART(WEEKDAY, GETDATE())-1)-14, GETDATE()), 23) AND od.AR_DATE < CONVERT(VARCHAR(10), DATEADD(DAY, 7-(DATEPART(WEEKDAY, GETDATE()))-7, GETDATE()), 23) THEN 1 ELSE 0 END AS IS_LAST_WEEK,
CASE WHEN od.AR_DATE >= DATEADD(MONTH, 0, DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)) AND od.AR_DATE < DATEADD(MONTH, 1, DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)) THEN 1 ELSE 0 END AS IS_THIS_MONTH,
CASE WHEN od.AR_DATE >= DATEADD(MONTH, -1, DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)) AND od.AR_DATE < DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1) THEN 1 ELSE 0 END AS IS_LAST_MONTH,
CASE WHEN od.AR_DATE >= DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE()), 0) AND od.AR_DATE < DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE())+1, 0) THEN 1 ELSE 0 END AS IS_THIS_QUARTER,
CASE WHEN od.AR_DATE >= DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE())-1, 0) AND od.AR_DATE < DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE()), 0) THEN 1 ELSE 0 END AS IS_LAST_QUARTER FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL odadd ON odadd.OD_JOB_NO = od.OD_JOB_NO WHERE od.AR_DATE >= DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE())-1, 0) AND od.AR_DATE < DATEADD(QUARTER, DATEDIFF(QUARTER, 0, GETDATE())+1, 0)
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
) T

/* OrderMapper.selectCSQanda : CS처리 */ WITH QANDA AS( SELECT REFERENCE_NO , COMPLETE_YNH , CUSTOMER_CODE FROM TB_ECM_QANDA WHERE 1=1 AND REGISTER_DATE_TIME >= CONVERT(VARCHAR(10), DATEADD(DAY , (CASE WHEN #{srchDateType} = '7' THEN -7 WHEN #{srchDateType} = '14' THEN -14 WHEN #{srchDateType} = '30' THEN -30 ELSE -7 END), GETDATE()) , 23) AND REGISTER_DATE_TIME < CONVERT(VARCHAR(10), DATEADD(DAY , (CASE WHEN #{srchDateType} = '7' THEN 7 WHEN #{srchDateType} = '14' THEN 14 WHEN #{srchDateType} = '30' THEN 30 ELSE 7 END), GETDATE()) , 23)
AND CUSTOMER_CODE = #{loginCustomerCd}
) SELECT 'CS' AS GUBUN , COUNT(REFERENCE_NO) CS_TOTAL , ISNULL(SUM(CASE WHEN ISNULL(COMPLETE_YNH, 'N') = 'N' THEN 1 ELSE 0 END),0) AS Q_CNT FROM QANDA UNION ALL SELECT 'COUPANG' AS GUBUN , COUNT(REFERENCE_NO) CS_TOTAL , ISNULL(SUM(CASE WHEN ISNULL(COMPLETE_YNH, 'N') = 'N' THEN 1 ELSE 0 END),0) AS Q_CNT FROM QANDA WHERE CUSTOMER_CODE IN ('COUPANG-CN','COUPANG-US','COUPANG-JP','COUPANG-JP')

