/* OrderMapper.updateUnusualInfo : 이례화물 update */
	UPDATE TB_ECM_OD_ADDITIONAL SET
		  UNUSUAL_CODE = #{unusualCode}
		  ,UNUSUAL_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

		  ,UNUSUAL_REASON = #{unusualReason}

	WHERE OD_JOB_NO = #{odJobNo}

/* OrderMapper.updateUnusualInfoBatch : 이례화물 update */
	UPDATE TB_ECM_OD_ADDITIONAL SET
	    UNUSUAL_CODE = #{unusualMap.unusualCode}
	    ,UNUSUAL_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

	    ,UNUSUAL_REASON = #{unusualMap.unusualReason}

	WHERE OD_JOB_NO IN (
	    SELECT od.OD_JOB_NO
	    FROM TB_ECM_OD od




	                    INNER JOIN TB_ECM_OD_ADDITIONAL ad
	                               ON ad.OD_JOB_NO = od.OD_JOB_NO
	                    WHERE (

	                        (od.MASTER_OD_JOB_NO = #{item.odJobNo} AND ISNULL(ad.SIMPLE_DOC_NO, '') = ISNULL(CAST(#{item.simpleDocNo} AS VARCHAR(20)), ''))

	                    )


	                    WHERE od.MASTER_OD_JOB_NO IN (
	                        #{item}
	                    )


	            AND od.BL_TYPE_MH = 'H'


	            WHERE od.OD_JOB_NO IN (
	                #{item}
	            )


	)

DELETE FROM ${podTable} WHERE OD_JOB_NO = #{OD_JOB_NO} AND POD_STATUS = #{podStatus};
INSERT INTO ${podTable} ( POD_JOB_NO, ENT_CODE, OD_JOB_NO, POD_STATUS, POD_NAME, POD_DATE, POD_TIME, BL_NO, REGISTER_USER_ID, REGISTER_DATE_TIME, UPDATE_USER_ID, UPDATE_DATE_TIME ) VALUES ( #{POD_JOB_NO}, #{ENT_CODE}, #{OD_JOB_NO}, #{podStatus}, #{POD_NAME}, #{POD_DATE}, #{POD_TIME}, #{HBL_NO}, #{updateUserId}, GETDATE(), #{updateUserId}, GETDATE() );
UPDATE TB_ECM_OD_ADDITIONAL SET LAST_POD_STATUS = #{podStatus}, LAST_POD_DATE = CONCAT(#{POD_DATE},' ',#{POD_TIME}) WHERE OD_JOB_NO = #{OD_JOB_NO};

