/* OrderMapper.updateReturnNo : 반품번호 업데이트(오더) */
UPDATE TB_ECM_OD
SET RETURN_DELIVERY_NO = #{deliveryNo}
WHERE OD_JOB_NO = #{odJobNo}
UPDATE TB_ECM_OD_ADDITIONAL
SET RETURN_DLV_REQ_DATE =  GETDATE()
WHERE OD_JOB_NO = #{odJobNo}

/* OrderMapper.updateReturnNoMulti : 반품번호 업데이트(멀티) */
UPDATE TB_ECM_OD_MULTI
SET RETURN_DELIVERY_NO = #{deliveryNo},
	RETURN_DLV_REQ_DATE = GETDATE()
WHERE OD_JOB_NO = #{odJobNo}
  AND SEQ_NO_ID = #{seqNoId}
